INSERT INTO causal_rules (id, code, sector, mission_id, title, rationale, rule_type, domain, cause_object, cause_attribute, operator, threshold, effect_object, effect_attribute, direction, source, confidence) VALUES
('cccccc01-0000-0000-0000-000000000001','R-STOCKOUT-CONV','retail','11111111-1111-1111-1111-111111111111','La rupture de stock d''un best-seller dégrade la conversion catégorie','Quand un best-seller reste indisponible plusieurs jours, les clientes ne convertissent pas vers un produit substitut. La sortie sans achat est massive.','measurable','supply','Inventory','days_stockout','>','3','Sales','category_conversion_rate','decrease','interview',0.92),
('cccccc01-0000-0000-0000-000000000002','R-CLIENTELING-ADOPT','retail','11111111-1111-1111-1111-111111111111','L''adoption du clienteling par les vendeurs augmente le panier moyen','Quand un vendeur a accès à l''historique cliente et à des recos produits, il propose la bonne pièce au bon moment.','measurable','sales','Vendor','clienteling_usage_rate','>','60','SalesOrder','average_basket','increase','interview',0.88),
('cccccc01-0000-0000-0000-000000000003','R-MAPE-ALLOC','retail','11111111-1111-1111-1111-111111111111','Un forecast peu précis force l''allocation manuelle des stocks magasin','Quand le MAPE dépasse 25%, les équipes Supply reprennent l''allocation à la main pour éviter ruptures et surstocks.','measurable','supply','Forecast','mape','>','25','Supply','manual_alloc_hours','increase','interview',0.90),
('cccccc01-0000-0000-0000-000000000004','R-PORTAIL-REJET','retail','11111111-1111-1111-1111-111111111111','Un portail fournisseur Excel-based génère des rejets de bons de commande','Quand les fournisseurs saisissent dans un Excel sans validation à la source, les erreurs de format sont massives.','measurable','supply','SupplierPortal','validation_layer','=','manual','PurchaseOrder','reject_rate','increase','interview',0.94),
('cccccc01-0000-0000-0000-000000000005','R-OTD-VISIBILITE','retail','11111111-1111-1111-1111-111111111111','L''absence de visibilité OTD amont retarde la réaction commerciale','Quand les retards fournisseurs sont découverts a posteriori, les équipes n''ont plus le temps de réagir commercialement.','measurable','supply','Supplier','otd_visibility','=','low','Retail','reaction_time','increase','interview',0.85),
('cccccc01-0000-0000-0000-000000000006','R-POC-INDUS','retail','11111111-1111-1111-1111-111111111111','Sans MLOps, les PoC IA restent au stade prototype','Quand l''entreprise n''a pas de plateforme MLOps, le passage de PoC à la production est bloqué.','measurable','operations','MLOps','platform_maturity','<','3','ML','prod_models_count','decrease','interview',0.95),
('cccccc01-0000-0000-0000-000000000007','R-LATENCE-CLIENTELING','retail','11111111-1111-1111-1111-111111111111','La latence J+1 des données clienteling dégrade la pertinence des recos','Quand les commandes web ne remontent au CRM qu''avec un jour de retard, le vendeur ne sait pas que la cliente a déjà acheté.','measurable','sales','DataFlow','latency_hours','>','4','Clienteling','recommendation_accuracy','decrease','interview',0.82),
('cccccc01-0000-0000-0000-000000000008','R-AOV-PERSO','retail','11111111-1111-1111-1111-111111111111','Sans personnalisation 1:1, l''AOV e-commerce stagne','Quand la personnalisation se limite à la segmentation par marché, l''AOV plafonne.','measurable','sales','Ecommerce','personalization_level','<','3','SalesOrder','aov','decrease','interview',0.80),
('cccccc01-0000-0000-0000-000000000009','R-ACCULTURATION','retail','11111111-1111-1111-1111-111111111111','L''absence de programme d''acculturation IA freine l''adoption en boutique','Quand les vendeurs n''ont pas été formés à l''IA, l''adoption stagne sous 40%.','measurable','people','Training','ai_program_exists','=','false','Adoption','rate_store','decrease','interview',0.87),
('cccccc01-0000-0000-0000-000000000010','R-DATALAKE-USAGE','retail','11111111-1111-1111-1111-111111111111','Un datalake non gouverné reste sous-exploité','Quand un datalake n''a pas de catalogue ni de data products, les métiers ne savent pas s''en servir.','measurable','data','DataLake','catalog_maturity','<','2','DataProduct','usage_count','decrease','interview',0.89),
('cccccc01-0000-0000-0000-000000000011','R-COMEX-CADENCE','retail','11111111-1111-1111-1111-111111111111','Un Comex peu fréquent ralentit les décisions stratégiques','Quand les arbitrages attendent un Comex toutes les 6 semaines, le cycle de décision dépasse 2 mois.','measurable','operations','Comex','frequency_weeks','>','4','Decision','cycle_time_days','increase','interview',0.83),
('cccccc01-0000-0000-0000-000000000012','R-DATA-SCI-BANDWIDTH','retail','11111111-1111-1111-1111-111111111111','Une équipe data science sous-staffée freine le passage en prod','Quand le ratio DS / use cases est < 1/5, les modèles n''atteignent pas la prod.','measurable','people','DataScience','headcount_ratio','<','0.2','ML','time_to_prod','increase','interview',0.86),
('cccccc01-0000-0000-0000-000000000013','R-SHIPTIFY-MANUEL','retail','11111111-1111-1111-1111-111111111111','Un TMS non intégré force la recopie manuelle des pré-avis livraison','Quand le TMS n''est connecté à l''ERP que par fichiers Excel, la donnée arrive en différé avec erreurs.','measurable','supply','TMS','integration_level','=','manual','Logistics','data_quality','decrease','interview',0.84),
('cccccc01-0000-0000-0000-000000000014','R-OMNICANAL-PARCOURS','retail','11111111-1111-1111-1111-111111111111','Un parcours web→boutique non unifié fait perdre des ventes','Quand le passage du web à la boutique ne déclenche aucune action assistée, la cliente n''est pas accompagnée.','measurable','sales','Journey','omnicanal_unified','=','false','SalesOrder','conversion_final','decrease','interview',0.81),
('cccccc01-0000-0000-0000-000000000015','R-USE-CASE-PRIO','retail','11111111-1111-1111-1111-111111111111','L''absence de priorisation des cas d''usage IA disperse les efforts','Quand le backlog IA n''est pas priorisé par valeur, les équipes data sont sollicitées de partout sans focus.','measurable','operations','Backlog','prioritization','=','false','DataTeam','focus_score','decrease','interview',0.88)
