('cccccc01-0000-0000-0000-000000000002','aaaaaaa1-0000-0000-0000-000000000001','Si l''IA ne se voit pas en boutique dans 12 mois, on a raté.',0.5),
('cccccc01-0000-0000-0000-000000000003','aaaaaaa1-0000-0000-0000-000000000003','Mon équipe passe 14h par semaine à faire des allocations Excel.',1.0),
('cccccc01-0000-0000-0000-000000000004','aaaaaaa1-0000-0000-0000-000000000005','18% des bons de commande sont rejetés parce que les fournisseurs renseignent mal le portail.',1.0),
