('cccccc01-0000-0000-0000-000000000005','aaaaaaa1-0000-0000-0000-000000000005','On découvre les retards 5 jours après — c''est trop tard pour réagir.',1.0),
('cccccc01-0000-0000-0000-000000000006','aaaaaaa1-0000-0000-0000-000000000006','On a 4 PoC IA qui dorment depuis 18 mois faute de mise en prod. Sans MLOps on ne passera jamais à l''échelle.',1.0),
('cccccc01-0000-0000-0000-000000000007','aaaaaaa1-0000-0000-0000-000000000004','Salesforce c''est un CRM, pas un assistant de vente.',0.7),
('cccccc01-0000-0000-0000-000000000008','aaaaaaa1-0000-0000-0000-000000000007','Notre conversion est bonne mais notre AOV stagne depuis 2 ans. On a la donnée mais pas les modèles pour personnaliser.',1.0),
('cccccc01-0000-0000-0000-000000000009','aaaaaaa1-0000-0000-0000-000000000008','On n''a pas de programme de formation IA, c''est notre angle mort.',1.0),
('cccccc01-0000-0000-0000-000000000010','aaaaaaa1-0000-0000-0000-000000000002','Notre datalake est riche mais les métiers ne savent pas s''en servir.',1.0),
('cccccc01-0000-0000-0000-000000000010','aaaaaaa1-0000-0000-0000-000000000006','Le métier nous demande des dashboards, on n''a pas le temps de faire du ML.',0.6),
('cccccc01-0000-0000-0000-000000000011','aaaaaaa1-0000-0000-0000-000000000001','Je veux des décisions plus rapides et mieux outillées, pas plus de dashboards.',1.0),
('cccccc01-0000-0000-0000-000000000012','aaaaaaa1-0000-0000-0000-000000000006','Les équipes data sont sollicitées de partout sans priorisation.',1.0),
('cccccc01-0000-0000-0000-000000000013','aaaaaaa1-0000-0000-0000-000000000002','Aucune intégration. Recopie manuelle des pré-avis livraison.',1.0),
('cccccc01-0000-0000-0000-000000000014','aaaaaaa1-0000-0000-0000-000000000007','La cliente passe du web à la boutique sans qu''on l''accompagne.',1.0),
('cccccc01-0000-0000-0000-000000000015','aaaaaaa1-0000-0000-0000-000000000008','Les équipes data sont sollicitées de partout sans priorisation.',1.0),
('cccccc01-0000-0000-0000-000000000015','aaaaaaa1-0000-0000-0000-000000000001','Trop de rapports, pas assez d''insights actionnables.',0.6)
